\begin{enumerate}

\item Berikan matriks transisi $\mat{P}$ bagi rantai Markov ini.

\item Tunjukkan bahwa rantai ini ergodik, tetapi tidak reguler.

\item Carilah vektor tetapnya.

\item Carilah banyaknya langkah yang diharapkan sebelum mencapai Ruangan~5 untuk
pertama kalinya jika dimulai dari Ruangan~1.
\end{enumerate}

\item\label{exer 12.1.13}
Dengan menggunakan Rumus Stirling, buktikan bahwa
$${{2n}\choose n} \sim \frac {2^{2n}}{\sqrt {\pi n}}\ .$$

\i\label{exer 3.1.13} Suatu negara bagian memiliki pelat nomor kendaraan yang memuat
tiga angka dan tiga huruf.  Berapa banyak pelat nomor berbeda yang mungkin

\begin{enumerate}
\item jika angka harus mendahului huruf?

\item jika tidak ada batasan mengenai letak huruf dan angka?
\end{enumerate}

\i\label{exer 4.1.13}
\begin{enumerate} 
\item Berapakah peluang bahwa pasangan bridge Anda memiliki tepat dua kartu as,
dengan syarat ia memiliki sekurang-kurangnya satu kartu as?

\item Berapakah peluang bahwa pasangan bridge Anda memiliki tepat dua kartu as,
dengan syarat ia memiliki kartu as sekop?
\end{enumerate}

\i\label{exer 4.1.15} Buktikan bahwa jika $A$ dan $B$ saling bebas, maka pasangan berikut juga saling bebas:
\begin{enumerate}
\item $A$ dan $\tilde B$.

\item $\tilde A$ dan $\tilde B$.
\end{enumerate}

\i\label{exer 5.1.10} Anggaplah peubah acak $X$ dan $Y$ memiliki distribusi gabungan
yang diberikan dalam Tabel~\ref{table 4.5}.
\begin{table}
\centering
\begin{tabular}{lr|rrrrr} 
     &     &  $Y$  &       &        &        \\
     &     &   -1  &  0    &  1     &  2     \\ \hline
$X$  & -1  &   0   & 1/36  &  1/6   & 1/12   \\
     &  0  & 1/18  &  0    &  1/18  &  0     \\
     &  1  &   0   & 1/36  &  1/6   & 1/12   \\
     &  2  & 1/12  &  0    &  1/12  & 1/6    \\
\end{tabular}
\caption{Distribusi gabungan.}
\label{table 4.5}
\end{table}

\begin{enumerate}
\item Berapakah $P(X \geq 1\ \mbox {dan\ } Y \leq 0)$?

\item Berapakah peluang bersyarat bahwa $Y \leq 0$ dengan syarat $X = 2$?

\item Apakah $X$ dan $Y$ saling bebas?

\item Bagaimanakah distribusi $Z = XY$?
\end{enumerate}

\i\label{exer 4.1.32} Misalkan $\Omega$ adalah ruang sampel suatu percobaan.  Misalkan $E$ adalah
kejadian dengan $P(E) > 0$ dan definisikan $m_E(\omega)$ dengan
$m_E(\omega) = m(\omega|E)$.  Buktikan bahwa $m_E(\omega)$ adalah fungsi distribusi pada
$E$, yakni bahwa $m_E(\omega) \geq 0$ dan $\sum_{\omega\in\Omega}
m_E(\omega) = 1$.  Fungsi $m_E$ disebut \emx {distribusi bersyarat dengan syarat $E$.}

\i\label{exer 4.1.9} Berapakah peluang bahwa suatu keluarga dengan dua anak mempunyai
\begin{enumerate}
\item dua anak laki-laki, dengan syarat sekurang-kurangnya satu anaknya laki-laki?

\item dua anak laki-laki, dengan syarat anak pertamanya laki-laki?
\end{enumerate}

\i\label{exer 9.2.20} Dalam salah satu kajian awal tentang distribusi Poisson, von
Bortkiewicz\index{von BORTKIEWICZ, L.}\footnote{L. von Bortkiewicz,  \emx {Das Gesetz der Kleinen
Zahlen} (Leipzig: Teubner, 1898), p.\ 24.} meninjau frekuensi kematian akibat
tendangan bagal\index{tendangan bagal} dalam korps tentara Prusia. Dari kajian atas
14 korps selama 20 tahun, ia memperoleh data pada Tabel~\ref{table 5.5}.
\begin{table}
\centering
\begin{tabular}{|c|c|}
\hline Jumlah kematian & Jumlah korps dengan $x$ kematian pada suatu tahun \\ \hline 
0 & 144 \\
1 & \hspace{.1in}91 \\ 
2 & \hspace{.1in}32 \\ 
3 & \hspace{.12in}11 \\ 
4 & \hspace{.18in}2 \\ \hline
\end{tabular}
\caption{Tendangan bagal.}
\label{table 5.5}
\end{table}
Sesuaikan distribusi Poisson pada data ini dan tentukan apakah menurut Anda distribusi
Poisson tersebut sesuai.

\i\label{exer 5.1.126}  
\begin{enumerate}
\item Hitung digit pertama dari 100 pangkat pertama bilangan 2, lalu tentukan seberapa
baik data ini sesuai dengan distribusi Benford.
\item Kalikan setiap bilangan dalam himpunan data pada bagian (a) dengan 3, lalu
bandingkan distribusi digit pertamanya dengan distribusi Benford.
\end{enumerate}

\i\label{exer 5.2.9} Misalkan $U$, $V$ adalah bilangan acak yang dipilih secara
independen dari interval $[0,1]$.  Carilah distribusi kumulatif dan densitas peubah acak
\begin{enumerate}
\item $Y = \max(U,V)$.

\item $Y = \min(U,V)$.
\end{enumerate}

\i\label{5.2.15} Misalkan $X$ adalah peubah acak dengan fungsi densitas
$$ f_X(x) = \left \{ \begin{array}{ll}
                cx(1 - x), & \mbox{jika $0 < x < 1$}, \\
                        0, & \mbox{selainnya.}
                  \end{array}
         \right.
$$
\begin{enumerate}
\item Berapakah nilai $c$?

\item Apakah fungsi distribusi kumulatif $F_X$ bagi $X$?

\item Berapakah peluang bahwa $X < 1/4$?
\end{enumerate}

\i\label{5.2.16} Misalkan $X$ adalah peubah acak dengan fungsi distribusi kumulatif
$$ F(x) =  \left \{ \begin{array}{ll}
                            0, & \mbox{jika $x < 0$}, \\
              \sin^2(\pi x/2), & \mbox{jika $0 \leq x \leq 1$},  \\
                            1, & \mbox{jika $1 < x$}.
                 \end{array}
        \right.
$$
\begin{enumerate}
\item Apakah fungsi densitas $f_X$ bagi $X$?

\item Berapakah peluang bahwa $X < 1/4$?
\end{enumerate}

\i\label{exer 5.2.1} Pilih bilangan $U$ dari interval satuan $[0,1]$ dengan
distribusi seragam.  Carilah distribusi kumulatif dan densitas peubah acak
\begin{enumerate}
\item $Y = U + 2$.

\item $Y = U^3$.
\end{enumerate}

\i\label{exer 5.2.2} Pilih bilangan $U$ dari interval $[0,1]$ dengan distribusi
seragam.  Carilah distribusi kumulatif dan densitas peubah acak
\begin{enumerate}
\item $Y = 1/(U + 1)$.

\item $Y = \log(U + 1)$.
\end{enumerate}

\i\label{exer 5.2.37} Misalkan $X$ adalah peubah acak yang memiliki densitas normal,
dan tinjau peubah acak $Y = e^X$.  Maka $Y$ memiliki densitas \emx {log-normal}
\index{fungsi densitas!log-normal}\index{densitas log-normal}.  Carilah densitas $Y$ ini.

\i\label{exer 5.2.4} Pilih bilangan $U$ dari interval $[0,1]$ dengan distribusi
seragam.  Carilah distribusi kumulatif dan densitas peubah acak
\begin{enumerate}
\item $Y = |U - 1/2|$.

\item $Y = (U - 1/2)^2$.
\end{enumerate}

\i\label{exer 5.2.6} Jelaskan cara menghasilkan peubah acak yang fungsi distribusi
kumulatifnya adalah
$$ F(x) =  \left \{ \begin{array}{ll}
              0, & \mbox{jika $x < 0$}, \\
            x^2, & \mbox{jika $0 \leq x \leq 1$}, \\
              1, & \mbox{jika $x > 1.$}
                 \end{array}
        \right.
$$

\i\label{exer 6.1.17} Gerolamo Cardano\index{CARDANO, G.}, dalam bukunya \emx {The Gambling Scholar,}
yang ditulis pada awal 1500-an, membahas permainan karnaval berikut. Terdapat enam
dadu. Setiap dadu memiliki lima sisi kosong. Sisi keenam memuat sebuah angka antara
1~dan~6---angka yang berbeda pada setiap dadu. Keenam dadu dilempar dan pemain
memenangi hadiah yang bergantung pada jumlah angka yang muncul.

\begin{enumerate}
\item Carilah, seperti yang dilakukan Cardano, nilai harapan jumlah tersebut tanpa mencari distribusinya.

\item Hadiah besar diberikan untuk jumlah yang besar, sedangkan biaya memainkan permainan ini tidak mahal.
Jelaskan mengapa hal ini dapat dilakukan.
\end{enumerate}

\i\label{exer 6.2.10} Buktikan fakta-fakta berikut tentang simpangan baku.
\begin{enumerate}
\item $D(X + c) = D(X)$.

\item $D(cX) = |c|D(X)$.
\end{enumerate}

\i\label{exer 9.2.109}  Peter dan Paul memainkan permainan cocok koin 10{,}000 kali.  Uraikan
secara singkat apa yang dinyatakan oleh setiap teorema berikut mengenai kekayaan Peter.
\begin{enumerate}
\item  Hukum Bilangan Besar.

\item  Teorema Limit Pusat.
\end{enumerate}

\i\label{exer 9.2.100}  Sebuah dadu dilempar 24 kali.  Gunakan Teorema Limit Pusat untuk
memperkirakan peluang bahwa
\begin{enumerate}
\item  jumlah hasil lemparannya lebih besar dari 84.

\item  jumlah hasil lemparannya sama dengan 84.
\end{enumerate}

